package com.nextgen.store.media;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class ImageStorageService { private final Path root; private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp"); public ImageStorageService(@Value("${app.storage.image-dir:./data/images}") String dir){root=Paths.get(dir).toAbsolutePath().normalize();try{Files.createDirectories(root);}catch(IOException e){throw new IllegalStateException("Unable to initialize image storage",e);}} public String store(MultipartFile f){if(f==null||f.isEmpty())throw new IllegalArgumentException("Image is required");if(!TYPES.contains(f.getContentType()))throw new IllegalArgumentException("Unsupported image type");String ext=switch(f.getContentType()){case "image/jpeg"->"jpg";case "image/png"->"png";default->"webp";};String key=UUID.randomUUID()+"."+ext;try{Files.copy(f.getInputStream(),root.resolve(key),StandardCopyOption.REPLACE_EXISTING);return key;}catch(IOException e){throw new IllegalStateException("Unable to store image",e);}} public Resource load(String key){if(key==null||!key.matches("[a-f0-9-]+\\.(jpg|png|webp)"))throw new IllegalArgumentException("Invalid image key");try{Path p=root.resolve(key).normalize();if(!p.startsWith(root)||!Files.exists(p))throw new NoSuchElementException("Image not found");return new Resource(p,Files.probeContentType(p));}catch(IOException e){throw new IllegalStateException("Unable to read image",e);}} public record Resource(Path path,String contentType){} }
